#!/usr/bin/env bash
set -euo pipefail

tmpl_file="/home/eval/app/app.conf.tmpl"
env_file="/home/eval/app/prod.env"
out_file="/home/eval/app/app.conf"

mapfile -t unresolved < <(awk -v outfile="$out_file" '
FILENAME == ARGV[1] {
    if ($0 ~ /^[[:space:]]*#/ || $0 ~ /^[[:space:]]*$/) next
    eq = index($0, "=")
    if (eq > 0) {
        k = substr($0, 1, eq - 1)
        v = substr($0, eq + 1)
        env[k] = v
        has[k] = 1
    }
    next
}
FILENAME == ARGV[2] {
    line = $0
    out = ""
    while (match(line, /[$][{][A-Za-z0-9_]+[}]/)) {
        out = out substr(line, 1, RSTART - 1)
        tok = substr(line, RSTART, RLENGTH)
        var = substr(tok, 3, RLENGTH - 3)
        if (var in has) {
            out = out env[var]
        } else {
            out = out tok
            unres[var] = 1
        }
        line = substr(line, RSTART + RLENGTH)
    }
    out = out line
    print out > outfile
}
END {
    close(outfile)
    for (var in unres) {
        print var
    }
}
' "$env_file" "$tmpl_file" | sort -u)

if (( ${#unresolved[@]} > 0 )); then
    echo "unresolved: ${unresolved[*]}"
else
    echo "unresolved:"
fi

exit 0
